/**
 * UNICODE'S JOINING TYPES AS SOURCE: `DerivedJoiningType.txt` (17.0, the version this was generated from, Node's and
 * production Chromium's Unicode) read into the letters that join (Joining_Type D, R, L and C), less the ones the pack's
 * own faces set (`packFallbackWidthData.SELF_HOSTED`: ZWJ), and written as `packJoiningData.ts`.
 * DerivedJoiningType.txt is https://www.unicode.org/Public/17.0.0/ucd/extracted/DerivedJoiningType.txt; the table is
 * regenerated by `joiningTypes.test.ts` with JOINING_TYPE_TXT set to its path.
 */
import { SELF_HOSTED } from '@/modules/accounting/services/packs/pages/packFallbackWidthData';

const JOINING = new Set(['D', 'R', 'L', 'C']);

/** Each code point `DerivedJoiningType.txt` gives a joining type of D, R, L or C. */
export function parseJoining(text: string): number[] {
  const out: number[] = [];
  for (const raw of text.split('\n')) {
    const line = raw.split('#')[0]!.trim();
    if (line === '') continue;
    const [range, type] = line.split(';').map((s) => s.trim());
    if (!JOINING.has(type!)) continue;
    const [from, to] = range!.split('..');
    for (let c = parseInt(from!, 16); c <= parseInt(to ?? from!, 16); c += 1) out.push(c);
  }
  return out.sort((a, b) => a - b);
}

export const selfHosted = (cp: number): boolean => SELF_HOSTED.some(([from, to]) => cp >= from && cp <= to);

/** The runs of consecutive joining code points the faces do not set: [first, last]. */
export function joiningRuns(codes: readonly number[]): Array<[number, number]> {
  const out: Array<[number, number]> = [];
  for (const code of codes) {
    if (selfHosted(code)) continue;
    const last = out[out.length - 1];
    if (last !== undefined && last[1] === code - 1) last[1] = code; else out.push([code, code]);
  }
  return out;
}

export function joiningSource(runs: ReadonlyArray<readonly [number, number]>): string {
  const lines = Array.from({ length: Math.ceil(runs.length / 8) }, (unused, i) => `  ${runs.slice(i * 8, i * 8 + 8).map(([a, b]) => `[0x${a.toString(16)}, 0x${b.toString(16)}]`).join(', ')},`).join('\n');
  return `/**
 * GENERATED by tests/unit/printParity/joiningTypes.ts from Unicode's DerivedJoiningType.txt (17.0): do not edit by hand.
 * Regenerate: JOINING_TYPE_TXT=<path> npx vitest run tests/unit/printParity/joiningTypes.test.ts
 *
 * The letters that join their neighbours (Joining_Type D, R, L or C: Arabic, Syriac, Mongolian, N'Ko, Adlam, Phags-pa,
 * Manichaean, ...) that the pack's own faces do not set, as runs [first, last]. Production sets a joined form, which
 * can be wider than the isolated form the fallback tables measure (\`packPrintedText.printsAnywhere\`).
 */
export const JOINING_FALLBACK: ReadonlyArray<readonly [number, number]> = [
${lines}
];
`;
}
